SELECT COALESCE(r.s_store_sk,          r.old__s_store_sk)::text          AS id,
       COALESCE(r.s_store_id,          r.old__s_store_id,          '')   AS store_id,
       COALESCE(r.s_rec_start_date,    r.old__s_rec_start_date,    '1900-01-01'::date) AS rec_start_date,
       COALESCE(r.s_rec_end_date,      r.old__s_rec_end_date,      '9999-12-31'::date) AS rec_end_date,
       COALESCE(r.s_closed_date_sk,    r.old__s_closed_date_sk,    0)    AS closed_date_sk,
       COALESCE(r.s_store_name,        r.old__s_store_name,        '')   AS store_name,
       COALESCE(r.s_number_employees,  r.old__s_number_employees,  0)    AS number_employees,
       COALESCE(r.s_floor_space,       r.old__s_floor_space,       0)    AS floor_space,
       COALESCE(r.s_hours,             r.old__s_hours,             '')   AS hours,
       COALESCE(r.s_manager,           r.old__s_manager,           '')   AS manager,
       COALESCE(r.s_market_id,         r.old__s_market_id,         0)    AS market_id,
       COALESCE(r.s_geography_class,   r.old__s_geography_class,   '')   AS geography_class,
       COALESCE(r.s_market_desc,       r.old__s_market_desc,       '')   AS market_desc,
       COALESCE(r.s_market_manager,    r.old__s_market_manager,    '')   AS market_manager,
       COALESCE(r.s_division_id,       r.old__s_division_id,       0)    AS division_id,
       COALESCE(r.s_division_name,     r.old__s_division_name,     '')   AS division_name,
       COALESCE(r.s_company_id,        r.old__s_company_id,        0)    AS company_id,
       COALESCE(r.s_company_name,      r.old__s_company_name,      '')   AS company_name,
       COALESCE(r.s_street_number,     r.old__s_street_number,     '')   AS street_number,
       COALESCE(r.s_street_name,       r.old__s_street_name,       '')   AS street_name,
       COALESCE(r.s_street_type,       r.old__s_street_type,       '')   AS street_type,
       COALESCE(r.s_suite_number,      r.old__s_suite_number,      '')   AS suite_number,
       COALESCE(r.s_city,              r.old__s_city,              '')   AS city,
       COALESCE(r.s_county,            r.old__s_county,            '')   AS county,
       COALESCE(r.s_state,             r.old__s_state,             '')   AS state,
       COALESCE(r.s_zip,               r.old__s_zip,               '')   AS zip,
       COALESCE(r.s_country,           r.old__s_country,           '')   AS country,
       COALESCE(r.s_gmt_offset,        r.old__s_gmt_offset,        0.0)::float8 AS gmt_offset,
       COALESCE(r.s_tax_precentage,    r.old__s_tax_precentage,    0.0)::float8 AS tax_precentage
FROM {{ .rows }}
